import{_ as r,c as t,o as a,a6 as s}from"./chunks/framework.bQzAl8Nj.js";const p=JSON.parse('{"title":"Subscriptions","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/subscriptions.md","filePath":"faq/subscriptions.md"}'),o={name:"faq/subscriptions.md"};function i(n,e,c,u,d,l){return a(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[s('<h1 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#is-there-a-subscription">Is there a subscription? ​</a></li><li><a href="#can-i-use-my-own-sim-card-and-or-server">Can I use my own SIM Card and/or server? ​</a></li><li><a href="#will-it-cost-me-extra-to-use-my-tracker-in-another-country">Will it cost me extra to use my tracker in another country? ​</a></li></ul></nav><h2 id="is-there-a-subscription" tabindex="-1">Is there a subscription? <a class="header-anchor" href="#is-there-a-subscription" aria-label="Permalink to &quot;Is there a subscription?&quot;">​</a></h2><p>Yes.</p><p>For general customers, a device must be activated with card details added to the account to start a subscription.</p><p>For business customers, with many devices or custom requirements we can offer alternative billing methods.</p><h2 id="can-i-use-my-own-sim-card-and-or-server" tabindex="-1">Can I use my own SIM Card and/or server? <a class="header-anchor" href="#can-i-use-my-own-sim-card-and-or-server" aria-label="Permalink to &quot;Can I use my own SIM Card and/or server?&quot;">​</a></h2><p>Our core products are designed to work with our own SIM cards and servers, and are thus non-replaceable.</p><p>This is to ensure the best possible service and security for our customers. All data transmitted by the devices is encrypted and needs to be processed on LightBug servers. We do however provide an API for retrieving data and controlling devices.</p><p>Our SIM cards are global and do not need changing, a full list of countries is <a href="https://lightbug.io/feature/worldwide-coverage/" target="_blank" rel="noreferrer">available here</a>. If your country is not listed, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us for a customised quote</a>.</p><p>If you still need to use your own SIM cards and have a requirement for 1000+ devices, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">please get in touch</a> regarding a custom device.</p><h2 id="will-it-cost-me-extra-to-use-my-tracker-in-another-country" tabindex="-1">Will it cost me extra to use my tracker in another country? <a class="header-anchor" href="#will-it-cost-me-extra-to-use-my-tracker-in-another-country" aria-label="Permalink to &quot;Will it cost me extra to use my tracker in another country?&quot;">​</a></h2><p>You don&#39;t have to worry about extra costs for using the device in any of the countries <a href="https://lightbug.io/feature/worldwide-coverage/" target="_blank" rel="noreferrer">listed here</a>.</p><p>And, there are no permanent roaming restrictions either - you can use the devices where you want, for as long as you want.</p>',14)]))}const m=r(o,[["render",i]]);export{p as __pageData,m as default};
